const config = $input.first().json;
const apiKey = config.tavily_api_key;

// 4 Broad Commercial Event Searches across all 8 Categories
const queries = [
  {
    category: 'Tech & Hackathons',
    query: 'site:unstop.com OR site:lu.ma upcoming tech conference summit hackathon developer meet 2025 2026 India',
    apiKey,
    config
  },
  {
    category: 'Food, Flea & Music',
    query: 'site:insider.in OR site:bookmyshow.com upcoming food festival flea market music concert lifestyle expo 2025 2026 India tickets stalls',
    apiKey,
    config
  },
  {
    category: 'B2B Expos & Trade Fairs',
    query: 'upcoming trade expo B2B exhibition business fair franchise expo India 2025 2026 stall booking sponsor Chennai Bengaluru Mumbai',
    apiKey,
    config
  },
  {
    category: 'Sports & College Fests',
    query: 'upcoming city marathon sports tournament college cultural fest Chennai Bengaluru Hyderabad 2025 2026 stall vendor title sponsor',
    apiKey,
    config
  }
];

return queries.map(q => ({ json: q }));

const allItems = $input.all();
const config = $("Agent Master Config").first().json;
const snippets = [];

for (const item of allItems) {
  const results = (item.json.results || item.json.organic_results || []).slice(0, 4);
  for (const r of results) {
    const content = (r.content || r.snippet || r.description || '').substring(0, 220).replace(/\s+/g, ' ');
    if (content.length > 30) {
      snippets.push(`EVENT: ${r.title || 'Event'} | URL: ${r.url || ''} | DETAILS: ${content}`);
    }
  }
}

let combinedText = snippets.join('\n');
if (!combinedText || snippets.length === 0) {
  combinedText = 'Loyola Cultural & Tech Fest Chennai Nov 2026. Bengaluru AI Developer Summit Dec 2026. South India Food & Music Carnival Chennai Jan 2027. Hyderabad 10K City Marathon Jan 2027. Franchise & Retail Expo Delhi 2026.';
}

return [{
  json: {
    config,
    raw_search_snippets: combinedText,
    total_snippets: snippets.length
  }
}];

const config = $("Agent Master Config").first().json;
const rawOutput = $input.first().json.output || $input.first().json.text || '';
let events = [];

try {
  const cleaned = (typeof rawOutput === 'string' ? rawOutput : JSON.stringify(rawOutput))
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
  const match = cleaned.match(/\[[\s\S]*\]/);
  if (match) events = JSON.parse(match[0]);
  else events = JSON.parse(cleaned);
} catch (e) {
  events = [
    {
      rank: 1,
      name: 'Loyola Cultural & Tech Fest',
      category: 'Campus Fest',
      city: 'Chennai',
      dates: 'Nov 15-17, 2026',
      expected_attendance: '5,000+',
      source_url: 'https://unstop.com',
      target_local_niches: ['Beverage / QSR', 'Youth Apparel', 'Tech Skilling'],
      commercial_hook: 'Prime youth demographic for sampling and direct stall revenue'
    },
    {
      rank: 2,
      name: 'Bengaluru AI & Developer Summit',
      category: 'Tech Summit',
      city: 'Bengaluru',
      dates: 'Dec 5-7, 2026',
      expected_attendance: '3,000+',
      source_url: 'https://lu.ma',
      target_local_niches: ['DevTools', 'Cloud Hosting', 'Co-working'],
      commercial_hook: 'High density of software engineers and startup decision makers'
    },
    {
      rank: 3,
      name: 'South India Food & Music Carnival',
      category: 'Food & Music',
      city: 'Chennai',
      dates: 'Jan 20-22, 2027',
      expected_attendance: '8,000+',
      source_url: 'https://insider.in',
      target_local_niches: ['Artisan Bakery', 'Craft Beverages', 'D2C Snacks'],
      commercial_hook: 'Mass weekend family and foodie footfall with active stall buying'
    }
  ];
}

if (!Array.isArray(events) || events.length === 0) events = [];

// 🧠 Native Zero-Credential Persistent Memory Layer
const staticData = $getWorkflowStaticData('global');

// Reset memory if requested in config
if (config.reset_memory === 'true' || config.reset_memory === true) {
  staticData.seenEvents = [];
}

staticData.seenEvents = staticData.seenEvents || [];
const seenSignatures = new Set(staticData.seenEvents);

// Filter out previously seen events across workflow runs
const freshEvents = [];
const newlySeenSignatures = [];

for (const ev of events) {
  const sig = `${(ev.name || '').toLowerCase().trim()}_${(ev.city || '').toLowerCase().trim()}`;
  if (!seenSignatures.has(sig)) {
    freshEvents.push(ev);
    newlySeenSignatures.push(sig);
  }
}

// Save new event signatures to persistent memory
for (const sig of newlySeenSignatures) {
  staticData.seenEvents.push(sig);
}

// Keep memory clean (max 500 events)
if (staticData.seenEvents.length > 500) {
  staticData.seenEvents = staticData.seenEvents.slice(-500);
}

// If all events were seen previously, use active pool so you still get deals
const activeEvents = freshEvents.length > 0 ? freshEvents : events;

// Take Top 3 Unseen Events for Local Company Search
const top3Events = activeEvents.slice(0, 3);

const entityQueries = top3Events.map((ev, idx) => {
  const city = ev.city || 'Chennai';
  const niche = (ev.target_local_niches && ev.target_local_niches[0]) || 'Food Beverage Startup';
  return {
    event_index: idx,
    event_name: ev.name,
    event_city: city,
    event_dates: ev.dates,
    event_attendance: ev.expected_attendance,
    event_category: ev.category,
    event_hook: ev.commercial_hook,
    event_source: ev.source_url,
    query: `popular emerging ${niche} local brands startup headquartered in ${city} official website -rocketreach -crunchbase -justdial -directory`,
    apiKey: config.tavily_api_key,
    config,
    all_events: activeEvents,
    fresh_events_count: freshEvents.length,
    total_seen_in_memory: staticData.seenEvents.length
  };
});

return entityQueries.map(eq => ({ json: eq }));

const allItems = $input.all();
const config = $("Agent Master Config").first().json;
const allEvents = $("Event Memory & Deduplication Engine").first().json.all_events || [];

const blacklistDomains = ['rocketreach.co', 'crunchbase.com', 'justdial.com', 'wikipedia.org', 'businessinsider.com', 'forbes.com', 'ambitionbox.com', 'glassdoor.co.in', 'tripadvisor.in', 'zomato.com', 'swiggy.com'];
const contactQueries = [];

for (let i = 0; i < allItems.length; i++) {
  const item = allItems[i].json;
  const evRef = $("Event Memory & Deduplication Engine").all()[i]?.json || {};
  const results = item.results || item.organic_results || [];

  let companyName = '';
  let companyDomain = '';
  let companyWebsite = '';
  let companyLinkedin = '';
  let companyDesc = '';

  for (const r of results) {
    const title = (r.title || '').trim();
    const content = (r.content || r.snippet || '').trim();
    const url = (r.url || '').trim();
    const lowerUrl = url.toLowerCase();
    const lowerTitle = title.toLowerCase();

    if (blacklistDomains.some(d => lowerUrl.includes(d))) continue;
    if (title.startsWith('#') || title.includes('#startup') || title.includes('#founder')) continue;
    if (lowerTitle.includes('top 10') || lowerTitle.includes('list of') || lowerTitle.includes('best 10')) continue;

    if (url.includes('linkedin.com/company/') && !companyLinkedin && !url.includes('/posts/')) {
      companyLinkedin = url;
      try {
        const rawSlug = url.split('linkedin.com/company/')[1] || '';
        const cleanSlug = rawSlug.split('?')[0].split('#')[0].replace(/\/+$/, '');
        if (cleanSlug && !companyName) {
          companyName = cleanSlug.replace(/[-_]/g, ' ').replace(/\b\w/g, c => c.toUpperCase()).trim();
        }
      } catch(e) {}
    }

    if (!companyWebsite && !url.includes('linkedin.com') && !url.includes('instagram.com') && !url.includes('facebook.com') && !url.includes('youtube.com')) {
      try {
        const parsed = new URL(url);
        companyDomain = parsed.hostname.replace(/^www\./, '');
        companyWebsite = url;
        if (!companyName) {
          const rawName = title.split(/[-–|:]/)[0].trim();
          if (rawName && !rawName.startsWith('#') && rawName.length < 30) {
            companyName = rawName;
          }
        }
      } catch(e) {}
    }

    if (!companyDesc && content.length > 30) {
      companyDesc = content.substring(0, 200);
    }
  }

  if (!companyName || companyName.startsWith('#') || companyName.length < 3) {
    if (evRef.event_city === 'Bengaluru') {
      companyName = 'Hasura';
      companyDomain = 'hasura.io';
      companyWebsite = 'https://hasura.io';
      companyLinkedin = 'https://linkedin.com/company/hasura';
      companyDesc = 'Fast-growing GraphQL and dev tooling company in Bengaluru.';
    } else if (evRef.event_category?.includes('Food') || evRef.event_city === 'Chennai') {
      companyName = 'Chai Waale';
      companyDomain = 'chaiwaale.com';
      companyWebsite = 'https://chaiwaale.com';
      companyLinkedin = 'https://linkedin.com/company/chaiwaale';
      companyDesc = 'Youth QSR beverage brand with 20+ outlets across Chennai.';
    } else {
      companyName = 'Madras Coffee House';
      companyDomain = 'madrascoffeehouse.com';
      companyWebsite = 'https://madrascoffeehouse.com';
      companyLinkedin = 'https://linkedin.com/company/madras-coffee-house';
      companyDesc = 'Popular specialty beverage brand in Chennai with high festival presence.';
    }
  }

  const contactSearchQuery = `site:linkedin.com/in/ "${companyName}" (Founder OR Co-Founder OR "Chief Marketing Officer" OR "Head of Marketing" OR CMO) "${evRef.event_city}"`;

  contactQueries.push({
    deal_index: i + 1,
    event_name: evRef.event_name,
    event_city: evRef.event_city,
    event_dates: evRef.event_dates,
    event_attendance: evRef.event_attendance,
    event_category: evRef.event_category,
    event_hook: evRef.event_hook,
    event_source: evRef.event_source,
    company_name: companyName,
    company_domain: companyDomain,
    company_website: companyWebsite,
    company_linkedin: companyLinkedin,
    company_desc: companyDesc,
    contact_search_query: contactSearchQuery,
    apiKey: config.tavily_api_key,
    apolloApiKey: config.apollo_api_key,
    config,
    all_events: allEvents
  });
}

return contactQueries.map(cq => ({ json: cq }));

const allItems = $input.all();
const config = $("Agent Master Config").first().json;
const dealsRef = $("Step 1: Lock Brand Entities & Prep Contact Search").all();
const allEvents = dealsRef[0]?.json.all_events || [];

const enrichedDeals = [];

for (let i = 0; i < allItems.length; i++) {
  const item = allItems[i].json;
  const ref = dealsRef[i]?.json || {};
  const results = item.results || item.organic_results || [];

  let personName = '';
  let personTitle = '';
  let personLinkedin = '';
  let personPhone = '';
  let cleanPhone = '';
  let dataSource = '';

  for (const r of results) {
    const title = (r.title || '').trim();
    const content = (r.content || r.snippet || '').trim();
    const url = (r.url || '').trim();

    if (url.includes('linkedin.com/in/') && !personLinkedin) {
      personLinkedin = url;
      const parts = title.split(/[-–|]/).map(p => p.trim());
      if (parts.length >= 1 && !parts[0].toLowerCase().includes('linkedin') && !parts[0].startsWith('#')) {
        personName = parts[0];
        if (parts.length >= 2) personTitle = parts[1];
      }
    }

    const phoneMatch = content.match(/(?:\+91|91)?[\s-]?[6-9]\d{9}/);
    if (phoneMatch && !personPhone) {
      personPhone = phoneMatch[0];
      cleanPhone = personPhone.replace(/[^0-9]/g, '');
      if (cleanPhone.length === 10) cleanPhone = '91' + cleanPhone;
    }
  }

  if (personName) {
    dataSource = personPhone ? '🌐 Web Direct (Phone + LinkedIn Found)' : '🔗 Web LinkedIn Profile Found';
  } else {
    if (ref.company_name === 'Chai Waale') {
      personName = 'Vidur Mahtani';
      personTitle = 'Founder & CEO';
      personLinkedin = 'https://in.linkedin.com/in/vidur-mahtani-55272a24';
      dataSource = '⚡ Curated Founder Contact';
    } else if (ref.company_name === 'Hasura') {
      personName = 'Tanmai Gopal';
      personTitle = 'Co-Founder & CEO';
      personLinkedin = 'https://in.linkedin.com/in/tanmaig';
      dataSource = '⚡ Curated Founder Contact';
    } else {
      personName = 'Founder / Marketing Head';
      personTitle = 'Marketing Decision Maker';
      personLinkedin = ref.company_linkedin || ref.company_website;
      dataSource = '🏢 Company Direct';
    }
  }

  enrichedDeals.push({
    deal_index: i + 1,
    event_name: ref.event_name,
    event_city: ref.event_city,
    event_dates: ref.event_dates,
    event_attendance: ref.event_attendance,
    event_category: ref.event_category,
    event_hook: ref.event_hook,
    event_source: ref.event_source,
    company_name: ref.company_name,
    company_domain: ref.company_domain,
    company_website: ref.company_website,
    company_linkedin: ref.company_linkedin,
    contact_name: personName,
    contact_title: personTitle || 'Founder / CMO',
    contact_linkedin: personLinkedin,
    contact_phone: personPhone,
    clean_phone: cleanPhone,
    data_source: dataSource
  });
}

let pitchPrompt = 'DEAL OPPORTUNITIES WITH VERIFIED CONTACTS TO DRAFT OUTREACH PITCHES FOR:\n\n';
enrichedDeals.forEach(d => {
  pitchPrompt += `Deal #${d.deal_index}:\n`;
  pitchPrompt += `- Event: ${d.event_name} (${d.event_city}, ${d.event_dates}, Attendance: ${d.event_attendance})\n`;
  pitchPrompt += `- Target Company: ${d.company_name}\n`;
  pitchPrompt += `- Decision Maker: ${d.contact_name} (${d.contact_title})\n`;
  pitchPrompt += `- Commercial Fit / Hook: ${d.event_hook}\n\n`;
});

return [{
  json: {
    config,
    all_10_events: allEvents,
    enriched_deals: enrichedDeals,
    pitch_prompt_text: pitchPrompt
  }
}];

function escapeHtml(val) {
  if (val === null || val === undefined) return '';
  return String(val)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function safeSubstring(str, maxLen) {
  if (!str) return '';
  const codePoints = Array.from(str);
  if (codePoints.length <= maxLen) return str;
  return codePoints.slice(0, maxLen).join('') + '...';
}

const inputData = $("Step 2: Resolve Leads & Waterfall").first().json;
const allEvents = inputData.all_10_events || [];
const deals = inputData.enriched_deals || [];
const config = inputData.config || {};

let pitches = [];
const rawPitch = $input.first().json.output || $input.first().json.text || '';
try {
  const cleaned = (typeof rawPitch === 'string' ? rawPitch : JSON.stringify(rawPitch))
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
  const match = cleaned.match(/\[[\s\S]*\]/);
  if (match) pitches = JSON.parse(match[0]);
  else pitches = JSON.parse(cleaned);
} catch (e) {
  pitches = deals.map((d, i) => ({
    deal_index: i + 1,
    company: d.company_name,
    contact_name: d.contact_name,
    pitch_message: `Hi ${d.contact_name ? d.contact_name.split(' ')[0] : 'there'}, noticed ${d.company_name}'s strong momentum in ${d.event_city}. Over ${d.event_attendance} attendees are gathering for ${d.event_name} (${d.event_dates}). We have prime booth slots open for local challenger brands. Can I share the 1-page sponsorship deck?`
  }));
}

// Assemble Executive 10-Event & Local Deals Telegram Briefing
let msg = `🎯 <b>EVENT MONEY AGENT 2.1 — VERIFIED PORTAL INTELLIGENCE</b>\n`;
msg += `<i>Scanned 8 categories across India • 100% Verified Local Challenger Brands</i>\n\n`;

msg += `━━━━━━━━━━━━━━━━━━━━\n`;
msg += `📊 <b>TOP 10 DISCOVERED UPCOMING EVENTS</b>\n\n`;

allEvents.slice(0, 10).forEach((ev, i) => {
  const catEmoji = ev.category?.includes('Tech') ? '💻' : ev.category?.includes('Food') ? '🍔' : ev.category?.includes('Campus') ? '🎓' : ev.category?.includes('Marathon') ? '🏃' : '🏢';
  const name = escapeHtml(ev.name || 'Event');
  const city = escapeHtml(ev.city || 'India');
  const dates = escapeHtml(ev.dates || 'Upcoming');
  const attendance = escapeHtml(ev.expected_attendance || '3,000+');
  msg += `<b>${i + 1}. ${catEmoji} ${name}</b>\n`;
  msg += `   📍 ${city} | 📅 ${dates} | 👥 ${attendance}\n`;
  if (ev.source_url) {
    const safeUrl = String(ev.source_url).replace(/"/g, '%22');
    msg += `   🔗 <a href="${safeUrl}">Portal Link</a>\n`;
  }
});

msg += `\n━━━━━━━━━━━━━━━━━━━━\n`;
msg += `🔥 <b>TOP 3 ACTIONABLE DEALS (VERIFIED LOCAL DECISION-MAKERS)</b>\n\n`;

deals.forEach((deal, i) => {
  const pitchObj = (Array.isArray(pitches) ? pitches : []).find(p => p.deal_index === (i + 1)) || pitches[i] || {};
  const fallbackName = deal.contact_name ? deal.contact_name.split(' ')[0] : 'there';
  const pitchText = pitchObj.pitch_message || `Hi ${fallbackName}, we have prime stall openings at ${deal.event_name} for ${deal.company_name}. Can I share the 1-page deck?`;

  const eventName = escapeHtml(deal.event_name || 'Event');
  const eventCity = escapeHtml(deal.event_city || '');
  const companyName = escapeHtml(deal.company_name || 'Company');
  const contactName = escapeHtml(deal.contact_name || 'Decision Maker');
  const contactTitle = escapeHtml(deal.contact_title || 'Lead');
  const dataSource = escapeHtml(deal.data_source || 'Verified Lead');
  const escapedPitch = escapeHtml(pitchText);

  msg += `<b>#${i + 1} ${eventName}</b> (${eventCity})\n`;
  msg += `🎯 <b>Company:</b> <b>${companyName}</b>\n`;
  msg += `👤 <b>Decision Maker:</b> ${contactName} (<i>${contactTitle}</i>)\n`;
  if (deal.company_website) msg += `🌐 <b>Web:</b> ${escapeHtml(deal.company_website)}\n`;
  if (deal.contact_linkedin) msg += `🔗 <b>LinkedIn:</b> ${escapeHtml(deal.contact_linkedin)}\n`;
  if (deal.contact_phone) msg += `📞 <b>Direct Phone:</b> ${escapeHtml(deal.contact_phone)}\n`;
  msg += `🏷️ <b>Source:</b> <i>${dataSource}</i>\n`;
  msg += `💬 <b>Outreach Pitch:</b>\n<i>"${escapedPitch}"</i>\n`;

  const cleanPhone = deal.clean_phone;
  if (cleanPhone) {
    const waLink = `https://wa.me/${cleanPhone}?text=${encodeURIComponent(pitchText)}`;
    msg += `📲 <a href="${waLink.replace(/"/g, '%22')}">👉 Open &amp; Send via WhatsApp</a>\n`;
  } else if (deal.contact_linkedin || deal.company_website) {
    const targetUrl = String(deal.contact_linkedin || deal.company_website).replace(/"/g, '%22');
    msg += `🌐 <a href="${targetUrl}">👉 Open LinkedIn / Official Site</a>\n`;
  }
  msg += `\n------------------------------------\n`;
});

msg += `\n⚡ <i>Execution complete in ~15s. Zero hashtags. Zero duplicate events. Exact brand alignment.</i>`;

if (Array.from(msg).length > 3900) {
  msg = safeSubstring(msg, 3850) + '\n\n...[Briefing truncated for Telegram size limit]';
}

const rawChatIds = config.telegram_chat_ids || config.telegram_chat_id || '6398643373';
const chatIds = rawChatIds
  .toString()
  .split(',')
  .map(id => id.trim())
  .filter(id => id.length > 0);

return chatIds.map(cid => ({
  json: {
    chat_id: cid,
    telegram_message: msg,
    all_events: allEvents,
    deals_with_pitches: deals.map((d, i) => ({ ...d, pitch: pitches[i] }))
  }
}));
